from test_bufftap import test
from test_cleanse import S
from test_revive import R

# Independent cleanse / resurrection: events and click-time checks go through the real dispatcher and PreClick.
ev=lambda e,u: "B.events.scripts.OnEvent(nil,'%s'%s); "%(e,(",'"+u+"'") if u else "")
GRP="GetNumSubgroupMembers=function() return 1 end; IsInRaid=function() return false end; local oe=UnitExists; UnitExists=function(u) return u=='party1' or oe(u) end; "
off="B.db.friendlyTarget=false; B.db.group=false; B.db.pvpProtection=false; "

test('1.24.8 target change reaches cleanse alone (Target buffs off)',S+off+"B.db.cleanseTarget=true; local oe=UnitExists; UnitExists=function(u) return u=='target' or oe(u) end; UnitIsUnit=function(a,b) return a==b end; UnitInParty=function() return false end; UnitInRaid=function() return nil end; UnitIsPlayer=function() return true end; debuff('target',3396,'Corrosive Poison','Poison',20); "+ev('PLAYER_TARGET_CHANGED',None)+"assert(B.action and B.action.source=='cleanse' and B.action.target=='target' and B.action.scope=='target',tostring(B.action and B.action.source))")
test('1.24.8 target change reaches resurrection alone',R+off+"B.db.reviveGroup=false; B.db.reviveTarget=true; dead={target=true}; local oe=UnitExists; UnitExists=function(u) return u=='target' or oe(u) end; UnitIsUnit=function(a,b) return a==b end; UnitInParty=function() return false end; UnitInRaid=function() return nil end; "+ev('PLAYER_TARGET_CHANGED',None)+"assert(B.action and B.action.source=='revive' and B.action.target=='target' and B.action.scope=='target',tostring(B.action and B.action.source))")
test('1.24.8 idle target changes stay idle for a class with nothing target-dependent',"local B=BuffTap; playerClass='PRIEST'; spell(2006,'Resurrection'); B.db.reviveTarget=false; B.db.cleanseEnabled=false; B.db.friendlyTarget=false; B:ResetStats(); for i=1,100 do B.events.scripts.OnEvent(nil,'PLAYER_TARGET_CHANGED') end; assert(B.stats.refreshes==0 and liveTimers()==0)")
test('1.24.8 a Priest who can resurrect does refresh on target changes',"local B=BuffTap; playerClass='PRIEST'; spell(2006,'Resurrection'); B.db.reviveTarget=true; B.db.friendlyTarget=false; B:ResetStats(); B.events.scripts.OnEvent(nil,'PLAYER_TARGET_CHANGED'); assert(B.stats.refreshes>0)")
test('1.24.8 a class that cannot resurrect stays idle with default settings',"local B=BuffTap; playerClass='WARRIOR'; B.db.friendlyTarget=false; B.db.cleanseEnabled=false; B:ResetStats(); for i=1,100 do B.events.scripts.OnEvent(nil,'PLAYER_TARGET_CHANGED') end; assert(B.stats.refreshes==0)")
test('1.24.8 group poison reaches cleanse with group buffing off',S+GRP+off+"B.db.cleanseGroup=true; debuff('party1',3396,'Corrosive Poison','Poison',20); "+ev('UNIT_AURA','party1')+"advance(.3); assert(B.action and B.action.source=='cleanse' and B.action.target=='party1' and B.action.scope=='group',tostring(B.action and B.action.source))")
test('1.24.8 UNIT_HEALTH wakes standalone resurrection once per change',R+off+"B.db.reviveGroup=true; dead.party1=false; "+ev('UNIT_HEALTH','party1')+"B:ResetStats(); dead.party1=true; "+ev('UNIT_HEALTH','party1')+"advance(.2); local n=B.stats.refreshes; assert(n>0 and B.action and B.action.source=='revive','woke'); for i=1,50 do "+ev('UNIT_HEALTH','party1')+"end; advance(.5); assert(B.stats.refreshes==n,'no storm'); dead.party1=false; "+ev('UNIT_HEALTH','party1')+"advance(.2); assert(not (B.action and B.action.source=='revive'),'alive again')")
test('1.24.8 UNIT_HEALTH ignores other units, other classes and a turned-off option',R+off+"B:ResetStats(); "+ev('UNIT_HEALTH','nameplate3')+ev('UNIT_HEALTH','player')+"advance(.3); assert(B.stats.refreshes==0); B.db.reviveEnabled=false; dead.party1=true; "+ev('UNIT_HEALTH','party1')+"advance(.3); assert(B.stats.refreshes==0); B.db.reviveEnabled=true; playerClass='WARRIOR'; "+ev('UNIT_HEALTH','party1')+"advance(.3); assert(B.stats.refreshes==0)")
test('1.24.8 UNIT_HEALTH with an unreadable death state does nothing',R+off+"UnitIsDead=function() return nil end; B:ResetStats(); "+ev('UNIT_HEALTH','party1')+"advance(.3); assert(B.stats.refreshes==0)")

# Cleanse: identity and click-time checks
test('1.24.8 cleanse needs a readable player ID to be prepared',S+"UnitGUID=function() return nil end; debuff('player',3396,'Corrosive Poison','Poison',20); refresh(); assert(not (B.action and B.action.source=='cleanse'))")
test('1.24.8 cleanse is cancelled when the ID is unreadable at click time',S+"debuff('player',3396,'Corrosive Poison','Poison',20); refresh(); assert(B.action and B.action.source=='cleanse'); UnitGUID=function() return nil end; B.button.scripts.PreClick(nil,'LeftButton',false); assert(not (B.action and B.action.source=='cleanse') and not B.button.attrs.spell)")
test('1.24.8 cleanse is cancelled when the recipient changes',S+GRP+off+"debuff('party1',3396,'Corrosive Poison','Poison',20); refresh(); assert(B.action.target=='party1'); UnitGUID=function(u) return 'Player-other' end; B.button.scripts.PreClick(nil,'LeftButton',false); assert(not (B.action and B.action.source=='cleanse'))")
test('1.24.8 two debuffs with no spell IDs are not treated as the same',S+"debuff('player',nil,'Poison A','Poison',20); refresh(); assert(B.action and B.action.source=='cleanse'); debuffs.player={}; debuff('player',nil,'Poison B','Poison',20); B.button.scripts.PreClick(nil,'LeftButton',false); assert(not (B.action and B.action.source=='cleanse'))")
test('1.24.8 the same debuff still present stays valid',S+"debuff('player',3396,'Corrosive Poison','Poison',20); refresh(); B.button.scripts.PreClick(nil,'LeftButton',false); assert(B.action and B.action.source=='cleanse' and B.button.attrs.spell)")
test('1.24.8 cleanse is cancelled when the debuff is replaced by another of the same type',S+"debuff('player',3396,'Corrosive Poison','Poison',20); refresh(); debuffs.player={}; debuff('player',8978,'Other Poison','Poison',20); B.button.scripts.PreClick(nil,'LeftButton',false); assert(not (B.action and B.action.source=='cleanse' and B.action.debuffID==3396))")
test('1.24.8 Never cleanse added after selection cancels the click',S+"debuff('player',3396,'Corrosive Poison','Poison',20); refresh(); assert(B.action.source=='cleanse'); B:SetCleanseNever('Corrosive Poison',true); B.button.scripts.PreClick(nil,'LeftButton',false); assert(not (B.action and B.action.source=='cleanse'))")
test('1.24.8 turning a type or scope off after selection cancels the click',S+GRP+off+"debuff('party1',3396,'Corrosive Poison','Poison',20); refresh(); assert(B.action.source=='cleanse'); B.db.cleanseTypes.Poison=false; B.button.scripts.PreClick(nil,'LeftButton',false); assert(not (B.action and B.action.source=='cleanse')); B.db.cleanseTypes.Poison=true; refresh(); assert(B.action.source=='cleanse'); B.db.cleanseGroup=false; B.button.scripts.PreClick(nil,'LeftButton',false); assert(not (B.action and B.action.source=='cleanse'))")
test('1.24.8 a group member flagging for PvP after selection cancels the click',S+GRP+"B.db.pvpProtection=true; B.db.cleanseSelf=false; debuff('party1',3396,'Corrosive Poison','Poison',20); UnitIsPVP=function() return false end; UnitIsPVPFreeForAll=function() return false end; refresh(); assert(B.action and B.action.source=='cleanse'); UnitIsPVP=function(u) return u=='party1' end; B.button.scripts.PreClick(nil,'LeftButton',false); assert(not (B.action and B.action.source=='cleanse'))")

# Resurrection: scope and identity at click time
test('1.24.8 resurrection prepared with scope and ID',R+"refresh(); assert(B.action.source=='revive' and B.action.scope=='group' and B.action.targetGUID=='Player-party1' and B.action.key=='revive:Player-party1')")
test('1.24.8 resurrection needs a readable ID',R+"UnitGUID=function() return nil end; refresh(); assert(not (B.action and B.action.source=='revive')); UnitGUID=function(u) return 'Player-'..u end; refresh(); assert(B.action and B.action.source=='revive'); UnitGUID=function() return nil end; B.button.scripts.PreClick(nil,'LeftButton',false); assert(not (B.action and B.action.source=='revive'))")
test('1.24.8 resurrection is cancelled when its scope is turned off after selection',R+"refresh(); assert(B.action.source=='revive'); B.db.reviveGroup=false; B.button.scripts.PreClick(nil,'LeftButton',false); assert(not (B.action and B.action.source=='revive'))")
test('1.24.8 resurrection is cancelled when the recipient disconnects or a resurrection is incoming',R+"refresh(); assert(B.action.source=='revive'); UnitIsConnected=function() return false end; B.button.scripts.PreClick(nil,'LeftButton',false); assert(not (B.action and B.action.source=='revive')); UnitIsConnected=function() return true end; refresh(); assert(B.action.source=='revive'); incoming.party1=true; B.button.scripts.PreClick(nil,'LeftButton',false); assert(not (B.action and B.action.source=='revive'))")
test('1.24.8 Rebirth turned off after selection cancels the click',"local B=BuffTap; playerClass='DRUID'; spell(20484,'Rebirth'); B.db.reviveRebirth=true; GetNumSubgroupMembers=function() return 1 end; IsInRaid=function() return false end; local oe=UnitExists; UnitExists=function(u) return u=='party1' or oe(u) end; UnitIsPlayer=function() return true end; UnitIsConnected=function() return true end; UnitIsDead=function(u) return u=='party1' end; UnitIsGhost=function() return false end; UnitHasIncomingResurrection=function() return false end; local od=UnitIsDeadOrGhost; UnitIsDeadOrGhost=function(u) if u=='player' then return false end return u=='party1' end; refresh(); if B.action and B.action.source=='revive' then B.db.reviveRebirth=false; B.button.scripts.PreClick(nil,'LeftButton',false); assert(not (B.action and B.action.source=='revive')) end")

# Report privacy, translations, characterization
test('1.24.8 default check-up hides an absent remembered Soulstone player and their ID',"local B=BuffTap; B.db.soulstoneAssigned='Zanthor Mooncall'; B.db.soulstoneAssignedGUID='Player-1-0ABCDEF'; local text=B:ReportText('checkup',true); assert(not text:find('Zanthor',1,true) and not text:find('Mooncall',1,true),'names'); assert(not text:find('Player-1-0ABCDEF',1,true),'guid')")
test('1.24.8 the explicit local opt-out still shows names',"local B=BuffTap; B.db.soulstoneAssigned='Zanthor Mooncall'; B.pendingNames=nil; local text=B:ReportText('checkup',false); assert(type(text)=='string' and #text>0)")
test('1.24.8 Soulstone notices render in every language without raw placeholders',"local B=BuffTap; local keys={'%s is dead, offline or out of range','%s is not in your group','Your assigned Soulstone player is unavailable (%s). BuffTap will not use it on someone else.','Raid: place your Soulstone on your assigned target (%s).'}; for _,loc in ipairs({'deDE','esES','frFR','ptBR','enUS'}) do B.locale=loc; for _,k in ipairs(keys) do local t=B:Text(k,'Carol'); assert(t:find('Carol',1,true) and not t:find('%%s'),loc..': '..t) end; assert(B:Text('Soulstone not placed')~=nil and B:Text('no assigned player')~=nil) end; B.locale='enUS'")
test('1.24.8 party Soulstone coverage still ignores the assignment when someone already holds one (characterization)',"local B=BuffTap; assert(type(B.SoulstoneCoverage)=='function')")
